<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { ArrowRight, BookOpen, CalendarClock, Check, ChevronLeft, ChevronRight, Clock3, FileArchive, FileText, History, Info, LoaderCircle, Play, Plus, RefreshCw, Search, ShieldCheck, Sparkles, Users } from '@lucide/vue'
import { api, errorMessage } from '../lib/api'
import { skillArtwork, uiArtwork } from '../lib/workspace-assets'
import type { Session, Skill, Schedule } from '../lib/types'
import AutomationModal from './AutomationModal.vue'
import AutomationScopePicker from './AutomationScopePicker.vue'
import AvatarPicker from './AvatarPicker.vue'

interface BusinessTask { id: string; name?: string; source?: string; projectVersion?: string; timeoutSeconds?: number; ready?: boolean }
interface TaskPlan extends Schedule { taskType?: 'agent' | 'business'; businessTaskId?: string; targetSessionId?: string; targetSessionName?: string; skillId?: string | null; prompt?: string; scheduleType?: string; executionMode?: string; runAt?: string; startDate?: string; time?: string; weekdays?: number[]; intervalMinutes?: number; nextRunAt?: string; lastRunAt?: string; lastStatus?: string }
interface TaskRun { id: string; scheduleId?: string; scheduleName?: string; status: string; taskType?: string; businessTaskId?: string; targetSessionId?: string; targetSessionName?: string; sessionId?: string; trigger?: string; requestedByName?: string; createdAt?: string; scheduledFor?: string; startedAt?: string; finishedAt?: string; executionMode?: string; error?: string; delivery?: { status: string; error?: string; channels?: { queued?: number; sent?: number; pending?: number; failed?: number } } }
type Dialog = 'import' | 'sharing' | 'detail' | 'schedule' | 'log' | 'use' | null
const props = defineProps<{ view: 'skills' | 'schedules'; sessions: Session[]; currentSessionId?: string }>()
const emit = defineEmits<{ toast: [message: string]; changed: []; 'open-session': [id: string, skillId?: string] }>()
const abort = new AbortController()
const skills = ref<Skill[]>([]), schedules = ref<TaskPlan[]>([]), runs = ref<TaskRun[]>([]), businessTasks = ref<BusinessTask[]>([]), catalogSessions = ref<Session[]>([])
const loading = ref(false), pageError = ref(''), dialogError = ref(''), activeDialog = ref<Dialog>(null), busy = ref(new Set<string>()), query = ref(''), page = ref(0)
const scheduleTab = ref<'plans' | 'runs'>('plans'), runFilter = ref<TaskPlan | null>(null), selectedSkill = ref<Skill | null>(null), editingSchedule = ref<TaskPlan | null>(null), selectedLog = ref<TaskRun | null>(null)
const logContent = ref(''), logTruncated = ref(false), useTarget = ref(''), skillFile = ref<File | null>(null)
const confirm = ref<{ kind: 'delete-skill' | 'delete-schedule' | 'run'; item: Skill | TaskPlan } | null>(null)
const skillForm = reactive({ enabled: false, scope: 'all', groupIds: [] as string[], avatarId: '' })
const planForm = reactive({ name: '', taskType: 'agent', businessTaskId: '', targetSessionId: '', executionMode: 'read-only', skillId: '', prompt: '', scheduleType: 'once', runAt: '', time: '08:00', startDate: '', weekdays: [1] as number[], intervalMinutes: 60, enabled: false })
const statusNames: Record<string, string> = { queued: '排队中', running: '运行中', succeeded: '已完成', failed: '执行失败', cancelled: '已取消', interrupted: '已中断', skipped: '已跳过' }
const deliveryNames: Record<string, string> = { pending: '等待投递', delivered: '已送达业务空间', failed: '投递失败', not_required: '无需投递' }
const weekdays = [{ id: 1, name: '周一' }, { id: 2, name: '周二' }, { id: 3, name: '周三' }, { id: 4, name: '周四' }, { id: 5, name: '周五' }, { id: 6, name: '周六' }, { id: 0, name: '周日' }]
let revision = 0, runRevision = 0, dialogRevision = 0, skillsRevision = 0, plansRevision = 0, groupsRevision = 0, businessRevision = 0, refreshTimer: ReturnType<typeof setInterval> | undefined, disposed = false, polling = false
const groups = computed(() => catalogSessions.value.length ? catalogSessions.value : props.sessions.filter(session => !session.taskWorker))
const scopeGroups = computed(() => selectedSkill.value?.scope === 'groups' ? selectedSkill.value.groupIds || [] : [])
const allowedUseGroups = computed(() => groups.value.filter(group => skillAvailable(selectedSkill.value, group.id)))
const availableSkills = computed(() => skills.value.filter(skill => skillAvailable(skill, planForm.targetSessionId)))
const selectedProject = computed(() => businessTasks.value.find(task => task.id === planForm.businessTaskId))
const missingSelectedProject = computed(() => !!planForm.businessTaskId && !selectedProject.value)
const selectedSkillUnavailable = computed(() => planForm.taskType === 'agent' && !!planForm.skillId && !availableSkills.value.some(skill => skill.id === planForm.skillId))
const editing = computed(() => busy.value.has('dialog'))
const filteredSkills = computed(() => skills.value.filter(skill => `${skill.name} ${skill.description || ''}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const filteredSchedules = computed(() => schedules.value.filter(schedule => `${schedule.name} ${schedule.prompt || ''} ${groupName(schedule)}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const filteredRuns = computed(() => runs.value.filter(run => `${run.scheduleName || ''} ${statusNames[run.status] || run.status} ${groupName(run)}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())))
const items = computed(() => props.view === 'skills' ? filteredSkills.value : scheduleTab.value === 'plans' ? filteredSchedules.value : filteredRuns.value)
const pageCount = computed(() => Math.max(1, Math.ceil(items.value.length / 9)))
const visibleSkills = computed(() => filteredSkills.value.slice(page.value * 9, (page.value + 1) * 9))
const visibleSchedules = computed(() => filteredSchedules.value.slice(page.value * 9, (page.value + 1) * 9))
const visibleRuns = computed(() => filteredRuns.value.slice(page.value * 9, (page.value + 1) * 9))
watch([query, scheduleTab, () => props.view, runFilter], () => { page.value = 0 })
watch(pageCount, count => { if (page.value >= count) page.value = count - 1 })
watch(() => planForm.taskType, kind => { if (kind === 'business') { planForm.scheduleType = 'daily'; planForm.executionMode = 'workspace' } })
watch(() => props.view, () => { query.value = ''; closeDialog(); confirm.value = null; void refresh() }, { immediate: true })
watch(dialogError, async message => {
  if (!message) return
  await nextTick()
  if (disposed) return
  const alert = document.querySelector<HTMLElement>('dialog[open] [role="alert"]')
  if (alert) { alert.tabIndex = -1; alert.focus() }
})

function request<T = any>(path: string, options: { method?: string; body?: unknown } = {}) { return api<T>(path, { ...options, signal: abort.signal }) }
function date(value?: string, fallback = '尚未执行') { if (!value) return fallback; const parsed = new Date(value); return Number.isNaN(parsed.getTime()) ? fallback : parsed.toLocaleString('zh-CN', { timeZone: 'Asia/Shanghai', hour12: false }) }
function dateInput(value?: string) { if (!value) return ''; const parsed = new Date(value); if (Number.isNaN(parsed.getTime())) return ''; return new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit', hour12: false }).format(parsed).replace(' ', 'T') }
function groupName(item: { targetSessionId?: string; targetSessionName?: string }) { return item.targetSessionName || groups.value.find(group => group.id === item.targetSessionId)?.title || (item.targetSessionId ? '智能体暂不可访问' : '尚未绑定智能体') }
function skillAvailable(skill: Skill | null | undefined, id: string) { return !!id && !!skill?.enabled && (skill.scope !== 'groups' || !!skill.groupIds?.includes(id)) }
function recurrence(schedule: TaskPlan) { if (schedule.scheduleType === 'once') return `仅一次 · ${date(schedule.runAt, '未设置时间')}`; if (schedule.scheduleType === 'daily') return `每天 ${schedule.time || ''}`; if (schedule.scheduleType === 'weekly') return `每${(schedule.weekdays || []).map(day => weekdays.find(value => value.id === day)?.name).join('、')} ${schedule.time || ''}`; return `每 ${schedule.intervalMinutes || 0} 分钟` }
function setBusy(key: string, value: boolean) { if (value) busy.value.add(key); else busy.value.delete(key) }
function notify(message: string) { emit('toast', message) }
function closeDialog() { if (editing.value) return; dialogRevision++; activeDialog.value = null; dialogError.value = ''; skillFile.value = null; logContent.value = ''; selectedLog.value = null }
function scopeBody() { if (skillForm.scope === 'groups' && !skillForm.groupIds.length) throw new Error('请至少选择一个共享智能体。'); return { scope: skillForm.scope, groupIds: skillForm.scope === 'groups' ? [...skillForm.groupIds] : [] } }
async function loadGroups() {
  const token = ++groupsRevision, result: Session[] = []; let offset = 0
  while (!disposed) {
    const data = await request<{ sessions: Session[]; total?: number }>(`/api/sessions?limit=200&offset=${offset}`)
    result.push(...data.sessions.filter(session => !session.taskWorker)); offset += data.sessions.length
    if (!data.sessions.length || offset >= (data.total || 0)) break
  }
  if (!disposed && token === groupsRevision) catalogSessions.value = result
}
async function loadSkills() { const token = ++skillsRevision, result = await request<{ skills: Skill[] }>('/api/skills'); if (!disposed && token === skillsRevision) skills.value = result.skills || [] }
async function loadPlans() { const token = ++plansRevision, result = await request<{ schedules: TaskPlan[] }>('/api/admin/schedules'); if (!disposed && token === plansRevision) schedules.value = result.schedules || [] }
async function loadBusinessTasks() { const token = ++businessRevision, result = await request<{ tasks: BusinessTask[] }>('/api/admin/business-tasks'); if (!disposed && token === businessRevision) businessTasks.value = result.tasks || [] }
async function loadRuns() {
  const token = ++runRevision, filter = runFilter.value?.id
  const result = await request<{ runs: TaskRun[] }>(filter ? `/api/admin/schedules/${encodeURIComponent(filter)}/runs?limit=100` : '/api/admin/task-runs?limit=100')
  if (!disposed && token === runRevision && filter === runFilter.value?.id) runs.value = result.runs || []
}
async function refresh(silent = false) {
  const token = ++revision
  if (!silent) { loading.value = true; pageError.value = '' }
  try {
    const jobs = props.view === 'skills' ? [loadSkills(), loadGroups()] : [loadPlans(), loadRuns(), ...(silent ? [] : [loadSkills(), loadGroups(), loadBusinessTasks()])]
    const results = await Promise.allSettled(jobs)
    const failed = results.find((result): result is PromiseRejectedResult => result.status === 'rejected')
    if (failed) throw failed.reason
  } catch (error) { if (!disposed && token === revision) pageError.value = errorMessage(error) }
  finally { if (!disposed && token === revision && !silent) loading.value = false }
}
async function act(key: string, action: () => Promise<void>) {
  if (busy.value.has(key)) return
  setBusy(key, true); pageError.value = ''
  try { await action() } catch (error) { if (!disposed) pageError.value = errorMessage(error) }
  finally { setBusy(key, false) }
}
async function openImport(skill?: Skill) {
  selectedSkill.value = skill || null; Object.assign(skillForm, { enabled: !!skill?.enabled, scope: skill?.scope === 'groups' ? 'groups' : 'all', groupIds: [...(skill?.groupIds || [])], avatarId: skill?.avatarId || '' }); skillFile.value = null; dialogError.value = ''; activeDialog.value = 'import'; dialogRevision++
  const token = dialogRevision
  try { await loadGroups() } catch (error) { if (!disposed && token === dialogRevision) dialogError.value = errorMessage(error) }
}
async function openDetail(skill: Skill, mode: 'detail' | 'sharing' = 'detail') {
  if (busy.value.has(`skill-${skill.id}`)) return
  const token = ++dialogRevision
  await act(`skill-${skill.id}`, async () => {
    const [result] = await Promise.all([request<{ skill: Skill }>(`/api/skills/${encodeURIComponent(skill.id)}`), loadGroups()])
    if (disposed || token !== dialogRevision) return
    selectedSkill.value = result.skill; Object.assign(skillForm, { enabled: !!result.skill.enabled, scope: result.skill.scope === 'groups' ? 'groups' : 'all', groupIds: [...(result.skill.groupIds || [])], avatarId: result.skill.avatarId || '' }); activeDialog.value = mode; dialogError.value = ''
  })
}
function chooseFile(event: Event) { const file = (event.target as HTMLInputElement).files?.[0]; skillFile.value = file || null; dialogError.value = file && (!/\.zip$/i.test(file.name) || file.size > 10 * 1024 * 1024) ? '请选择不超过 10 MB 的 ZIP 文件。' : '' }
async function saveSkill() {
  if (editing.value) return
  const token = dialogRevision, selected = selectedSkill.value, mode = activeDialog.value
  let committed = false
  setBusy('dialog', true); dialogError.value = ''
  try {
    const sharing = scopeBody()
    if (skillForm.avatarId && !/^portrait-(?:0[1-9]|1[0-4])$/.test(skillForm.avatarId)) throw new Error('请选择有效的技能头像。')
    if (mode === 'sharing' && selected) await request(`/api/admin/skills/${encodeURIComponent(selected.id)}`, { method: 'PATCH', body: { ...sharing, avatarId: skillForm.avatarId } })
    else {
      const file = skillFile.value
      if (!file || !/\.zip$/i.test(file.name) || file.size > 10 * 1024 * 1024) throw new Error('请选择不超过 10 MB 的 ZIP 文件。')
      const bytes = new Uint8Array(await file.arrayBuffer()); let binary = ''
      for (let offset = 0; offset < bytes.length; offset += 32768) binary += String.fromCharCode(...bytes.subarray(offset, offset + 32768))
      await request(`/api/admin/skills/import${selected ? `/${encodeURIComponent(selected.id)}` : ''}`, { method: 'POST', body: { zipBase64: btoa(binary), enabled: skillForm.enabled, ...sharing, avatarId: skillForm.avatarId } })
    }
    committed = true
    if (disposed) return
    emit('changed'); await loadSkills(); notify(mode === 'sharing' ? '技能头像与授权范围已更新。' : '技能 ZIP 已导入。')
  } catch (error) {
    if (!disposed && token === dialogRevision) {
      if (committed) { pageError.value = `更改已保存，但刷新目录失败：${errorMessage(error)}`; notify('更改已保存，请刷新目录查看。') }
      else dialogError.value = errorMessage(error)
    }
  }
  finally { setBusy('dialog', false); if (!disposed && committed && token === dialogRevision) closeDialog() }
}
async function toggleSkill(skill: Skill) { await act(`skill-${skill.id}`, async () => { await request(`/api/admin/skills/${encodeURIComponent(skill.id)}`, { method: 'PATCH', body: { enabled: !skill.enabled } }); await loadSkills(); emit('changed'); notify(skill.enabled ? '技能已停用。' : '技能已启用。') }) }
function useSkill() { if (!selectedSkill.value?.enabled) return; useTarget.value = allowedUseGroups.value.some(group => group.id === props.currentSessionId) ? props.currentSessionId || '' : allowedUseGroups.value.length === 1 ? allowedUseGroups.value[0]!.id : ''; activeDialog.value = 'use' }
function enterSkill() { if (!selectedSkill.value || !skillAvailable(selectedSkill.value, useTarget.value)) { dialogError.value = '请选择已授权的智能体。'; return }; const skill = selectedSkill.value, target = useTarget.value; closeDialog(); emit('open-session', target, skill.id) }

async function openSchedule(schedule?: TaskPlan) {
  editingSchedule.value = schedule || null
  Object.assign(planForm, { name: schedule?.name || '', taskType: schedule?.taskType || 'agent', businessTaskId: schedule?.businessTaskId || '', targetSessionId: schedule?.targetSessionId || props.currentSessionId || '', executionMode: schedule?.executionMode === 'workspace' ? 'workspace' : 'read-only', skillId: schedule?.skillId || '', prompt: schedule?.prompt || '', scheduleType: schedule?.scheduleType || 'once', runAt: dateInput(schedule?.runAt), time: schedule?.time || '08:00', startDate: schedule?.startDate || '', weekdays: [...(schedule?.weekdays || [1])], intervalMinutes: schedule?.intervalMinutes || 60, enabled: !!schedule?.enabled })
  activeDialog.value = 'schedule'; dialogError.value = ''; dialogRevision++
  const token = dialogRevision
  setBusy('dialog-load', true)
  try { await Promise.all([loadSkills(), loadGroups(), loadBusinessTasks()]); if (!disposed && token === dialogRevision && !groups.value.some(group => group.id === planForm.targetSessionId)) planForm.targetSessionId = '' }
  catch (error) { if (!disposed && token === dialogRevision) dialogError.value = errorMessage(error) }
  finally { if (token === dialogRevision || activeDialog.value !== 'schedule') setBusy('dialog-load', false) }
}
async function saveSchedule() {
  if (editing.value || busy.value.has('dialog-load')) return
  const schedule = editingSchedule.value, token = dialogRevision, business = planForm.taskType === 'business', type = business ? 'daily' : planForm.scheduleType
  let committed = false
  const wasEnabled = planForm.enabled
  setBusy('dialog', true); dialogError.value = ''
  try {
    if (!planForm.name.trim()) throw new Error('请填写任务名称。')
    if (!groups.value.some(group => group.id === planForm.targetSessionId)) throw new Error('请选择你已加入的智能体。')
    if (business && (!selectedProject.value || selectedProject.value.ready === false)) throw new Error('请选择运行环境可用的业务项目。')
    if (!business && selectedSkillUnavailable.value) throw new Error('此智能体当前不可使用所选技能，请重新选择。')
    if (!business && !planForm.prompt.trim()) throw new Error('请填写执行任务。')
    const body: Record<string, unknown> = { name: planForm.name.trim(), taskType: business ? 'business' : 'agent', targetSessionId: planForm.targetSessionId, executionMode: business ? 'workspace' : planForm.executionMode, skillId: business ? null : planForm.skillId || null, prompt: business ? `执行 RPAC 业务项目 ${planForm.businessTaskId}，将最终执行结果投递到绑定业务群。` : planForm.prompt.trim(), scheduleType: type, enabled: planForm.enabled }
    if (business) { body.businessTaskId = planForm.businessTaskId; body.startDate = planForm.startDate || null }
    if (type === 'once') {
      const unchanged = !!schedule?.runAt && dateInput(schedule.runAt) === planForm.runAt
      const instant = new Date(unchanged ? schedule!.runAt! : `${planForm.runAt}:00+08:00`)
      if (!planForm.runAt || Number.isNaN(instant.getTime()) || (instant.getTime() <= Date.now() && !(unchanged && !planForm.enabled))) throw new Error('请选择未来的北京时间；历史计划可保持停用。')
      body.runAt = instant.toISOString()
    }
    if (type === 'daily' || type === 'weekly') { if (!/^([01]\d|2[0-3]):[0-5]\d$/.test(planForm.time)) throw new Error('请选择有效执行时刻。'); body.time = planForm.time }
    if (type === 'weekly') { if (!planForm.weekdays.length) throw new Error('请至少选择一个执行日。'); body.weekdays = [...planForm.weekdays] }
    if (type === 'interval') { if (!Number.isSafeInteger(Number(planForm.intervalMinutes)) || Number(planForm.intervalMinutes) < 1 || Number(planForm.intervalMinutes) > 5256000) throw new Error('执行间隔必须是 1 至 5,256,000 分钟的整数。'); body.intervalMinutes = Number(planForm.intervalMinutes) }
    await request(schedule ? `/api/admin/schedules/${encodeURIComponent(schedule.id)}` : '/api/admin/schedules', { method: schedule ? 'PATCH' : 'POST', body })
    committed = true
    if (disposed) return
    emit('changed'); await loadPlans(); notify(wasEnabled ? '任务已保存并启用计划。' : '任务已保存，计划保持停用。')
  } catch (error) {
    if (!disposed && token === dialogRevision) {
      if (committed) { pageError.value = `任务已保存，但刷新列表失败：${errorMessage(error)}`; notify('任务已保存，请刷新列表查看。') }
      else dialogError.value = errorMessage(error)
    }
  }
  finally { setBusy('dialog', false); if (!disposed && committed && token === dialogRevision) closeDialog() }
}
async function toggleSchedule(schedule: TaskPlan) { await act(`schedule-${schedule.id}`, async () => { await request(`/api/admin/schedules/${encodeURIComponent(schedule.id)}`, { method: 'PATCH', body: { enabled: !schedule.enabled } }); await loadPlans(); notify(schedule.enabled ? '计划已停用。' : '计划已启用。') }) }
async function showRuns(schedule?: TaskPlan) { runFilter.value = schedule || null; scheduleTab.value = 'runs'; query.value = ''; await act('runs', loadRuns) }
function tabKeydown(event: KeyboardEvent) {
  if (!['ArrowLeft', 'ArrowRight', 'Home', 'End'].includes(event.key)) return
  event.preventDefault()
  const tab = event.key === 'Home' ? 'plans' : event.key === 'End' ? 'runs' : scheduleTab.value === 'plans' ? 'runs' : 'plans'
  if (tab === 'runs') void showRuns(runFilter.value || undefined)
  else scheduleTab.value = 'plans'
  void nextTick(() => document.getElementById(`automation-tab-${tab}`)?.focus())
}
async function runAction(run: TaskRun, action: 'cancel' | 'retry-delivery') { await act(`run-${run.id}`, async () => { await request(`/api/admin/task-runs/${encodeURIComponent(run.id)}/${action}`, { method: 'POST', body: {} }); await Promise.all([loadRuns(), loadPlans()]); notify(action === 'cancel' ? '已提交取消请求。' : '已重试投递现有结果，任务不会重新执行。') }) }
async function confirmAction() {
  const action = confirm.value; if (!action || busy.value.has('confirm')) return
  setBusy('confirm', true); dialogError.value = ''
  try {
    const id = encodeURIComponent(action.item.id)
    if (action.kind === 'run') {
      const result = await request<{ run?: TaskRun }>(`/api/admin/schedules/${id}/run`, { method: 'POST', body: {} })
      confirm.value = null; await showRuns(action.item as TaskPlan); await loadPlans(); notify(result.run?.status === 'skipped' ? '今天已执行过此业务项目，本次已跳过。' : '任务已提交，最终结果将自动投递到绑定业务空间。')
    } else {
      await request(`/api/admin/${action.kind === 'delete-skill' ? 'skills' : 'schedules'}/${id}`, { method: 'DELETE', body: {} }); confirm.value = null; await (action.kind === 'delete-skill' ? loadSkills() : loadPlans()); emit('changed'); notify(action.kind === 'delete-skill' ? '技能已删除。' : '定时任务已删除。')
    }
  } catch (error) { if (!disposed) dialogError.value = errorMessage(error) }
  finally { setBusy('confirm', false) }
}
function askConfirm(kind: 'delete-skill' | 'delete-schedule' | 'run', item: Skill | TaskPlan) { dialogError.value = ''; confirm.value = { kind, item } }
async function openLog(run: TaskRun) { selectedLog.value = run; activeDialog.value = 'log'; dialogError.value = ''; logContent.value = ''; logTruncated.value = false; dialogRevision++; await refreshLog() }
async function refreshLog() {
  if (!selectedLog.value || busy.value.has('log')) return
  const id = selectedLog.value.id, token = dialogRevision; setBusy('log', true); dialogError.value = ''
  try { const result = await request<{ content?: string; truncated?: boolean }>(`/api/admin/task-runs/${encodeURIComponent(id)}/log`); if (!disposed && token === dialogRevision && selectedLog.value?.id === id) { logContent.value = result.content || '尚无执行日志。'; logTruncated.value = !!result.truncated } }
  catch (error) { if (!disposed && token === dialogRevision) dialogError.value = errorMessage(error) }
  finally { setBusy('log', false) }
}
onMounted(() => { refreshTimer = setInterval(async () => { if (props.view !== 'schedules' || document.hidden || polling || loading.value || editing.value || busy.value.size) return; polling = true; try { await refresh(true) } finally { polling = false } }, 5000) })
onBeforeUnmount(() => { disposed = true; revision++; runRevision++; dialogRevision++; abort.abort(); if (refreshTimer) clearInterval(refreshTimer) })
</script>

<template>
  <section class="automation-page">
    <header class="page-heading"><div><span class="section-kicker">{{ view === 'skills' ? 'CAPABILITIES' : 'AUTOMATION' }}</span><h1>{{ view === 'skills' ? '技能中心' : '定时任务' }}</h1><p>{{ view === 'skills' ? '为专业智能体配置能力，让每一次协作都有方法可循。' : '让智能体与业务项目按时处理工作，将结果送达业务空间。' }}</p></div><div class="heading-buttons"><button class="btn" :disabled="loading" @click="refresh()"><RefreshCw :class="{ spinning: loading }" />刷新</button><button class="btn btn-primary" @click="view === 'skills' ? openImport() : openSchedule()"><Plus />{{ view === 'skills' ? '导入技能' : '新建任务' }}</button></div></header>
    <div v-if="pageError" class="error-box" role="alert">{{ pageError }}<button class="inline-link" @click="refresh()">重新加载</button></div>
    <div class="summary-strip"><div class="summary-item"><span class="summary-icon"><BookOpen v-if="view === 'skills'" :size="20" /><CalendarClock v-else :size="20" /></span><div><strong>{{ view === 'skills' ? skills.length : schedules.length }}</strong><span>{{ view === 'skills' ? '已接入技能' : '任务计划' }}</span></div></div><div class="summary-item"><span class="summary-icon green"><Check :size="20" /></span><div><strong>{{ view === 'skills' ? skills.filter(skill => skill.enabled).length : schedules.filter(schedule => schedule.enabled).length }}</strong><span>{{ view === 'skills' ? '已启用' : '运行中的计划' }}</span></div></div><div class="summary-context"><ShieldCheck :size="17" /><span>{{ view === 'skills' ? '仅管理员可配置 · 按智能体授权使用' : 'Asia/Shanghai · 北京时间 · 服务需保持运行' }}</span></div></div>
    <div class="list-toolbar"><div v-if="view === 'schedules'" class="segmented" role="tablist" aria-label="定时任务视图" @keydown="tabKeydown"><button id="automation-tab-plans" role="tab" aria-controls="automation-panel-plans" :tabindex="scheduleTab === 'plans' ? 0 : -1" :aria-selected="scheduleTab === 'plans'" :class="{ selected: scheduleTab === 'plans' }" @click="scheduleTab = 'plans'"><CalendarClock :size="16" />任务计划</button><button id="automation-tab-runs" role="tab" aria-controls="automation-panel-runs" :tabindex="scheduleTab === 'runs' ? 0 : -1" :aria-selected="scheduleTab === 'runs'" :class="{ selected: scheduleTab === 'runs' }" @click="showRuns(runFilter || undefined)"><History :size="16" />运行记录</button></div><div v-else class="list-caption">技能目录 <span>{{ skills.length }}</span></div><label class="list-search"><Search :size="17" /><input v-model="query" type="search" :placeholder="view === 'skills' ? '搜索技能名称或说明' : '搜索任务或智能体'" :aria-label="view === 'skills' ? '搜索技能' : '搜索任务与运行记录'" /></label></div>
    <div v-if="view === 'schedules' && scheduleTab === 'runs'" class="run-filter"><span>{{ runFilter ? `${runFilter.name} · 运行记录` : '全部任务 · 最近 100 条运行记录' }}</span><button v-if="runFilter" class="inline-link" @click="showRuns()">查看全部记录</button><span class="refresh-note">每 5 秒自动更新</span></div>
    <div :id="view === 'schedules' ? `automation-panel-${scheduleTab}` : undefined" :role="view === 'schedules' ? 'tabpanel' : undefined" :aria-labelledby="view === 'schedules' ? `automation-tab-${scheduleTab}` : undefined">
    <div v-if="loading && !items.length" class="empty-state" role="status"><LoaderCircle class="spinning" :size="28" /><h2>正在加载{{ view === 'skills' ? '技能目录' : '任务数据' }}</h2><p>请稍候…</p></div>
    <template v-else-if="view === 'skills'">
      <div v-if="visibleSkills.length" class="skill-grid"><article v-for="skill in visibleSkills" :key="skill.id" class="panel skill-card"><div class="card-top"><span class="capability-icon" aria-hidden="true"><img :src="skillArtwork(skill.name,skill.avatarId)" alt="" width="32" height="32" loading="lazy" decoding="async" /></span><span class="badge" :class="skill.enabled ? 'status-succeeded' : 'status-idle'">{{ skill.enabled ? '已启用' : '已停用' }}</span></div><button class="skill-title" @click="openDetail(skill)">{{ skill.name }}</button><p class="skill-description">{{ skill.description || '暂无技能说明' }}</p><div class="skill-scope"><Users :size="14" /><span>{{ skill.scope === 'groups' ? `已授权 ${skill.groupIds?.length || 0} 个智能体` : '全部智能体共享' }}</span></div><div class="skill-version">版本 {{ skill.version || 1 }}<span>更新于 {{ date(skill.updatedAt, '未记录') }}</span></div><div class="card-actions"><button class="btn" :disabled="busy.has(`skill-${skill.id}`)" @click="openDetail(skill)">详情</button><button class="btn" :disabled="busy.has(`skill-${skill.id}`)" @click="openDetail(skill, 'sharing')">配置</button><button class="btn" :disabled="busy.has(`skill-${skill.id}`)" @click="openImport(skill)">更新 ZIP</button><button class="inline-link" :disabled="busy.has(`skill-${skill.id}`)" @click="toggleSkill(skill)">{{ skill.enabled ? '停用' : '启用' }}</button><button class="inline-link danger-text" :disabled="busy.has(`skill-${skill.id}`)" @click="askConfirm('delete-skill', skill)">删除</button></div></article></div>
      <div v-else class="empty-state"><BookOpen :size="34" /><h2>{{ query ? '没有找到匹配的技能' : '为智能体添加第一项能力' }}</h2><p>{{ query ? '试试其他名称或关键词。' : '导入包含 SKILL.md 的 ZIP 技能包，并选择可使用它的智能体。' }}</p><button v-if="!query" class="btn btn-primary" @click="openImport()"><Plus />导入技能 ZIP</button></div>
    </template>
    <template v-else-if="scheduleTab === 'plans'">
      <div v-if="visibleSchedules.length" class="plan-list"><article v-for="schedule in visibleSchedules" :key="schedule.id" class="panel plan-card"><div class="plan-heading"><span class="plan-icon" :class="{ business: schedule.taskType === 'business' }" aria-hidden="true"><img :src="schedule.taskType === 'business' ? uiArtwork.business : uiArtwork.calendar" alt="" width="30" height="30" loading="lazy" decoding="async" /></span><div class="plan-name"><h2>{{ schedule.name }}</h2><p>{{ recurrence(schedule) }}<span v-if="schedule.startDate"> · 从 {{ schedule.startDate }} 起</span></p></div><span class="badge" :class="schedule.enabled ? 'status-succeeded' : 'status-idle'">{{ schedule.enabled ? '计划已启用' : '计划已停用' }}</span></div><p class="plan-description">{{ schedule.taskType === 'business' ? `直接执行 ${businessTasks.find(task => task.id === schedule.businessTaskId)?.name || schedule.businessTaskId || '业务项目'}，自动投递最终结果。` : schedule.prompt }}</p><div class="plan-details"><span><Users :size="14" />{{ groupName(schedule) }}</span><span><BookOpen :size="14" />{{ schedule.taskType === 'business' ? '业务项目 · 每天最多执行一次' : schedule.skillId ? skills.find(skill => skill.id === schedule.skillId)?.name || '技能暂不可用' : '普通 AI 任务' }}</span><span v-if="schedule.taskType !== 'business'"><ShieldCheck :size="14" />{{ schedule.executionMode === 'workspace' ? '执行技能与命令' : '文件只读' }}</span></div><div class="plan-timing"><div><span>下次执行</span><strong>{{ date(schedule.nextRunAt, schedule.enabled ? '暂无后续计划' : '计划尚未启用') }}</strong></div><div><span>上次执行</span><strong>{{ date(schedule.lastRunAt) }}</strong></div><span v-if="schedule.lastStatus" class="badge" :class="`status-${schedule.lastStatus}`">{{ statusNames[schedule.lastStatus] || schedule.lastStatus }}</span></div><p v-if="!schedule.targetSessionId" class="binding-warning">请编辑任务并绑定智能体，之后才能运行或启用计划。</p><div class="card-actions"><button class="btn" :disabled="!schedule.targetSessionId || busy.has(`schedule-${schedule.id}`)" @click="askConfirm('run', schedule)"><Play :size="14" />立即运行</button><button class="btn" @click="showRuns(schedule)"><History :size="14" />运行记录</button><button class="btn" @click="openSchedule(schedule)">编辑</button><button class="inline-link" :disabled="busy.has(`schedule-${schedule.id}`) || (!schedule.enabled && !schedule.targetSessionId)" @click="toggleSchedule(schedule)">{{ schedule.enabled ? '停用计划' : '启用计划' }}</button><button class="inline-link danger-text" :disabled="busy.has(`schedule-${schedule.id}`)" @click="askConfirm('delete-schedule', schedule)">删除</button></div></article></div>
      <div v-else class="empty-state"><CalendarClock :size="34" /><h2>{{ query ? '没有找到匹配的任务' : '把重复工作交给智能体' }}</h2><p>{{ query ? '试试其他名称或关键词。' : '设置执行时间、能力与结果投递目标，创建可持续运行的工作计划。' }}</p><button v-if="!query" class="btn btn-primary" @click="openSchedule()"><Plus />新建定时任务</button></div>
    </template>
    <template v-else>
      <div v-if="visibleRuns.length" class="plan-list"><article v-for="run in visibleRuns" :key="run.id" class="panel run-card"><div class="run-heading"><span class="run-avatar"><History :size="18" /></span><div><h2>{{ run.scheduleName || '历史任务' }}</h2><p>{{ run.trigger === 'manual' ? '手动触发' : '计划触发' }} · {{ run.requestedByName || '计划调度' }}</p></div><span class="badge" :class="`status-${run.status}`">{{ statusNames[run.status] || run.status }}</span></div><div class="run-details"><span>业务空间：{{ groupName(run) }}</span><span>{{ run.trigger === 'manual' ? '提交时间' : '计划时间' }}：{{ date(run.trigger === 'manual' ? run.createdAt : run.scheduledFor, '未记录') }}</span><span>开始：{{ date(run.startedAt, '尚未开始') }}</span><span>结束：{{ date(run.finishedAt, '尚未结束') }}</span></div><div v-if="run.delivery" class="delivery-line"><span>结果投递</span><span class="badge" :class="run.delivery.status === 'failed' ? 'status-failed' : run.delivery.status === 'delivered' ? 'status-succeeded' : 'status-idle'">{{ deliveryNames[run.delivery.status] || run.delivery.status }}</span><small v-if="run.delivery.channels && (run.delivery.channels.sent || run.delivery.channels.pending || run.delivery.channels.failed || run.delivery.channels.queued)">消息渠道：送达 {{ run.delivery.channels.sent || 0 }} · 待送达 {{ run.delivery.channels.pending || 0 }} · 失败 {{ run.delivery.channels.failed || 0 }}</small></div><p v-else class="legacy-note">历史记录未包含自动投递状态。</p><details v-if="run.error" class="run-error"><summary>查看执行信息</summary><pre>{{ run.error }}</pre></details><details v-if="run.delivery?.error" class="run-error"><summary>查看投递信息</summary><pre>{{ run.delivery.error }}</pre></details><div class="card-actions"><button v-if="run.targetSessionId" class="btn" @click="emit('open-session', run.targetSessionId)">打开业务空间<ArrowRight :size="14" /></button><button v-if="run.sessionId" class="btn" @click="emit('open-session', run.sessionId)">执行会话</button><button v-if="run.taskType === 'business'" class="btn" @click="openLog(run)"><FileText :size="14" />执行日志</button><button v-if="['succeeded', 'failed'].includes(run.status) && (run.delivery?.status === 'failed' || (run.delivery?.channels?.failed || 0) > 0)" class="btn" :disabled="busy.has(`run-${run.id}`)" @click="runAction(run, 'retry-delivery')">补发结果</button><button v-if="['queued', 'running'].includes(run.status)" class="inline-link danger-text" :disabled="busy.has(`run-${run.id}`)" @click="runAction(run, 'cancel')">取消运行</button></div></article></div>
      <div v-else class="empty-state"><History :size="34" /><h2>{{ query ? '没有匹配的运行记录' : '暂无运行记录' }}</h2><p>{{ query ? '试试其他关键词。' : '任务触发后，可以在这里查看执行状态和结果投递情况。' }}</p></div><p class="page-footnote"><Info :size="15" />补发只重试已有结果，不会重新执行任务。服务重启后中断的任务不会自动重跑。</p>
    </template>
    </div>
    <div v-if="pageCount > 1" class="pagination"><span>共 {{ items.length }} 项 · 第 {{ page + 1 }} / {{ pageCount }} 页</span><button class="btn" :disabled="page === 0" aria-label="上一页" @click="page--"><ChevronLeft /></button><button class="btn" :disabled="page >= pageCount - 1" aria-label="下一页" @click="page++"><ChevronRight /></button></div>

    <AutomationModal :open="activeDialog === 'import' || activeDialog === 'sharing'" :title="activeDialog === 'sharing' ? '设置技能头像与授权范围' : selectedSkill ? '更新技能 ZIP' : '导入技能 ZIP'" :description="activeDialog === 'sharing' ? `技能：${selectedSkill?.name || ''}。更改后，智能体与其定时任务按新范围使用。` : '导入完整技能包，自动识别 SKILL.md 中的名称、说明和正文。'" :busy="editing" @close="closeDialog">
      <form id="skill-management-form" class="form-stack" @submit.prevent="saveSkill"><div v-if="dialogError" class="error-box" role="alert">{{ dialogError }}</div><template v-if="activeDialog === 'import'"><label class="upload-area" for="skill-zip"><FileArchive :size="32" /><strong>{{ skillFile ? skillFile.name : '选择技能 ZIP 文件' }}</strong><span>{{ skillFile ? `${(skillFile.size / 1024 / 1024).toFixed(2)} MB` : '最大 10 MB · 每次导入一个技能' }}</span><input id="skill-zip" type="file" accept=".zip,application/zip" required :disabled="editing" @change="chooseFile" /></label><p class="form-help">包含一个 SKILL.md，可附带 scripts、references、assets 等文件。{{ selectedSkill ? `当前版本 ${selectedSkill.version || 1}，新包将替换完整技能包。` : '' }}</p></template><AvatarPicker v-model="skillForm.avatarId" :disabled="editing" label="技能头像" /><AutomationScopePicker v-model:scope="skillForm.scope" v-model:groupIds="skillForm.groupIds" :sessions="groups" /><label v-if="activeDialog === 'import'" class="checkbox-row"><input v-model="skillForm.enabled" type="checkbox" /><span>导入后启用，允许获授权智能体使用</span></label></form>
      <template #footer><button class="btn" :disabled="editing" @click="closeDialog">取消</button><button class="btn btn-primary" form="skill-management-form" type="submit" :disabled="editing"><LoaderCircle v-if="editing" class="spinning" />{{ editing ? '保存中…' : activeDialog === 'sharing' ? '保存配置' : '导入 ZIP' }}</button></template>
    </AutomationModal>
    <AutomationModal :open="activeDialog === 'detail'" :title="selectedSkill?.name || '技能详情'" :description="`版本 ${selectedSkill?.version || 1} · ${selectedSkill?.enabled ? '已启用' : '已停用'} · ${date(selectedSkill?.updatedAt, '未记录更新时间')}`" wide @close="closeDialog"><div class="detail-meta"><div class="skill-detail-identity"><span v-if="selectedSkill" class="capability-icon" aria-hidden="true"><img :src="skillArtwork(selectedSkill.name,selectedSkill.avatarId)" alt="" width="32" height="32" decoding="async" /></span><span class="badge">{{ selectedSkill?.scope === 'groups' ? `授权 ${scopeGroups.length} 个智能体` : '全部智能体共享' }}</span></div><p>{{ selectedSkill?.description }}</p><p v-if="selectedSkill?.scope === 'groups'" class="form-help">{{ scopeGroups.map(id => groups.find(group => group.id === id)?.title || '已授权智能体（目前不可访问）').join('、') || '尚未选择智能体' }}</p></div><h3 class="detail-label">技能指令 · SKILL.md</h3><pre class="skill-content">{{ selectedSkill?.content || '暂无指令正文。' }}</pre><details v-if="selectedSkill?.files?.length" class="run-error"><summary>配套文件 · {{ selectedSkill.files.length }} 个</summary><ul class="file-list"><li v-for="file in selectedSkill.files" :key="file.path"><span>{{ file.path }}</span><small>{{ file.size }} 字节</small></li></ul></details><template #footer><button class="btn" @click="selectedSkill && openImport(selectedSkill)">更新 ZIP</button><button class="btn btn-primary" :disabled="!selectedSkill?.enabled" @click="useSkill">在智能体中使用<ArrowRight /></button></template></AutomationModal>
    <AutomationModal :open="activeDialog === 'use'" title="选择使用此技能的智能体" description="仅展示你已加入且获授权的智能体业务空间。" @close="closeDialog"><form id="use-skill-form" class="form-stack" @submit.prevent="enterSkill"><div v-if="dialogError" class="error-box" role="alert">{{ dialogError }}</div><div class="field"><label for="skill-use-target">智能体</label><select id="skill-use-target" v-model="useTarget" class="input" required><option value="">{{ allowedUseGroups.length ? '请选择智能体' : '暂无可使用此技能的智能体' }}</option><option v-for="group in allowedUseGroups" :key="group.id" :value="group.id">{{ group.title }}</option></select><small>进入后会为本次消息选择此技能；补充任务要求再发送。</small></div></form><template #footer><button class="btn" @click="closeDialog">取消</button><button type="submit" form="use-skill-form" class="btn btn-primary" :disabled="!allowedUseGroups.length">进入业务空间<ArrowRight /></button></template></AutomationModal>

    <AutomationModal :open="activeDialog === 'schedule'" :title="editingSchedule ? '编辑定时任务' : '新建定时任务'" description="选择处理方式、执行时间和结果投递目标。协作成员只看到最终结果。" :busy="editing" wide @close="closeDialog"><form id="schedule-management-form" class="form-stack" @submit.prevent="saveSchedule"><div v-if="dialogError" class="error-box" role="alert">{{ dialogError }}</div><div v-if="busy.has('dialog-load')" class="form-help" role="status">正在加载可用智能体与项目…</div><div class="form-columns"><div class="field"><label for="schedule-kind">任务类型</label><select id="schedule-kind" v-model="planForm.taskType" class="input" :disabled="!!editingSchedule"><option value="agent">AI 任务</option><option value="business">业务项目</option></select><small>{{ editingSchedule ? '已保存任务的类型保持不变。' : 'AI 任务使用模型；业务项目直接执行已接入项目。' }}</small></div><div class="field"><label for="schedule-name">任务名称</label><input id="schedule-name" v-model="planForm.name" class="input" required maxlength="120" placeholder="例如：每日提柜数据同步" /></div></div><div class="field"><label for="schedule-target">绑定智能体</label><select id="schedule-target" v-model="planForm.targetSessionId" class="input" required><option value="">{{ groups.length ? '请选择智能体' : '请先创建或加入智能体' }}</option><option v-for="group in groups" :key="group.id" :value="group.id">{{ group.title }}</option></select><small>仅列出你已加入的智能体；最终结果同时同步该空间已绑定的消息渠道。</small></div>
      <template v-if="planForm.taskType === 'business'"><div class="field"><label for="schedule-business-project">业务项目</label><select id="schedule-business-project" v-model="planForm.businessTaskId" class="input" required><option value="">请选择已接入的业务项目</option><option v-for="task in businessTasks" :key="task.id" :value="task.id">{{ task.name || task.id }}{{ task.ready === false ? ' · 暂不可用' : '' }}</option><option v-if="missingSelectedProject" :value="planForm.businessTaskId">{{ planForm.businessTaskId }} · 项目不可用</option></select><small v-if="selectedProject">{{ selectedProject.source || 'RPAC' }}{{ selectedProject.projectVersion ? ` · ${selectedProject.projectVersion}` : '' }}{{ selectedProject.timeoutSeconds ? ` · 最长 ${Math.ceil(selectedProject.timeoutSeconds / 60)} 分钟` : '' }}{{ selectedProject.ready === false ? ' · 请检查项目运行环境' : '' }}</small></div><div class="form-notice"><Info :size="17" /><p>直接执行项目，不调用模型。每天最多执行一次，失败不会自动重跑；手动运行也计入当天限制。执行日志仅管理员可见。</p></div></template>
      <template v-else><div class="form-columns"><div class="field"><label for="schedule-mode">执行权限</label><select id="schedule-mode" v-model="planForm.executionMode" class="input"><option value="read-only">文件只读 · 读取与分析</option><option value="workspace">执行技能与命令</option></select></div><div class="field"><label for="schedule-skill">使用技能（可选）</label><select id="schedule-skill" v-model="planForm.skillId" class="input" :aria-invalid="selectedSkillUnavailable"><option value="">不指定技能</option><option v-for="skill in availableSkills" :key="skill.id" :value="skill.id">{{ skill.name }}</option><option v-if="selectedSkillUnavailable" :value="planForm.skillId">原选技能 · 当前智能体不可用</option></select></div></div><p class="form-help" :class="{ 'danger-text': selectedSkillUnavailable }">{{ selectedSkillUnavailable ? '请重新选择当前智能体已授权并启用的技能。' : planForm.executionMode === 'workspace' ? '允许执行技能脚本、系统命令、文件修改及网络请求。' : '只读文件与分析，不执行脚本、命令及网络请求。调用业务接口请选择执行权限。' }}</p><div class="field"><label for="schedule-prompt">执行任务</label><textarea id="schedule-prompt" v-model="planForm.prompt" class="input" rows="4" required placeholder="说明处理资料、执行要求和结果格式…" /></div></template>
      <div class="form-columns"><div class="field"><label for="schedule-frequency">执行频率</label><select id="schedule-frequency" v-model="planForm.scheduleType" class="input" :disabled="planForm.taskType === 'business'"><option value="once">仅执行一次</option><option value="daily">每天</option><option value="weekly">每周</option><option value="interval">按分钟间隔</option></select></div><div v-if="planForm.scheduleType === 'once'" class="field"><label for="schedule-once">执行时间 · 北京时间</label><input id="schedule-once" v-model="planForm.runAt" type="datetime-local" class="input" required step="60" /></div><div v-else-if="planForm.scheduleType === 'daily' || planForm.scheduleType === 'weekly'" class="field"><label for="schedule-time">执行时刻 · 北京时间</label><input id="schedule-time" v-model="planForm.time" type="time" class="input" required step="60" /></div><div v-else class="field"><label for="schedule-interval">间隔分钟数</label><input id="schedule-interval" v-model.number="planForm.intervalMinutes" type="number" class="input" required min="1" step="1" /></div></div><div v-if="planForm.taskType === 'business'" class="field"><label for="schedule-start-date">首次计划日期 · 北京时间</label><input id="schedule-start-date" v-model="planForm.startDate" type="date" class="input" /><small>从此日期起按设定时刻运行；手动运行仍会立即提交。留空使用服务端默认起始日期。</small></div><fieldset v-if="planForm.scheduleType === 'weekly'" class="weekday-field"><legend>每周执行日</legend><div><label v-for="day in weekdays" :key="day.id" :class="{ checked: planForm.weekdays.includes(day.id) }"><input v-model="planForm.weekdays" type="checkbox" :value="day.id" />{{ day.name }}</label></div></fieldset><div class="form-notice"><Clock3 :size="17" /><p>计划按 Asia/Shanghai（UTC+08:00）解释，不受当前电脑时区影响。服务需保持运行。</p></div><label class="checkbox-row"><input v-model="planForm.enabled" type="checkbox" /><span>启用计划，保存后按设定时间执行</span></label><p class="form-help">新任务默认停用。请确认执行权限、目标智能体与时间后启用。</p></form><template #footer><button class="btn" :disabled="editing" @click="closeDialog">取消</button><button type="submit" form="schedule-management-form" class="btn btn-primary" :disabled="editing || busy.has('dialog-load')"><LoaderCircle v-if="editing" class="spinning" />{{ editing ? '保存中…' : '保存任务' }}</button></template></AutomationModal>

    <AutomationModal :open="activeDialog === 'log'" :title="`${selectedLog?.scheduleName || '业务任务'} · 执行日志`" description="仅管理员可查看，日志不会发送到业务空间。" wide @close="closeDialog"><div v-if="dialogError" class="error-box" role="alert">{{ dialogError }}</div><pre class="business-log" tabindex="0">{{ busy.has('log') && !logContent ? '正在加载执行日志…' : logContent || '尚无执行日志。' }}</pre><p class="form-help">{{ logTruncated ? '日志较长，仅显示部分内容。' : '' }}运行中可以刷新查看最新日志。</p><template #footer><button class="btn" :disabled="busy.has('log')" @click="refreshLog"><RefreshCw :class="{ spinning: busy.has('log') }" />刷新日志</button><button class="btn btn-primary" @click="closeDialog">关闭</button></template></AutomationModal>
    <AutomationModal :open="!!confirm" :title="confirm?.kind === 'run' ? '立即运行任务？' : confirm?.kind === 'delete-skill' ? '删除技能？' : '删除定时任务？'" :busy="busy.has('confirm')" @close="confirm = null"><p class="confirmation-copy">{{ confirm?.kind === 'run' ? `即将提交「${confirm.item.name}」，按当前配置执行并投递结果。` : `即将删除「${confirm?.item.name}」。` }}</p><p class="form-help">{{ confirm?.kind === 'run' ? (confirm.item.taskType === 'business' ? '业务项目会立即执行真实业务操作，并计入当天一次的执行限制。今天已执行过的项目会跳过。' : '任务独立执行，最终结果自动投递到已绑定的智能体业务空间。') : confirm?.kind === 'delete-skill' ? '被定时任务引用的技能需要先解除引用，删除后无法在技能中心恢复。' : '删除后将停止未来计划，已有会话与历史结果仍可查看。' }}</p><div v-if="dialogError" class="error-box" role="alert">{{ dialogError }}</div><template #footer><button class="btn" :disabled="busy.has('confirm')" @click="confirm = null">取消</button><button class="btn" :class="confirm?.kind === 'run' ? 'btn-primary' : 'btn-danger'" :disabled="busy.has('confirm')" @click="confirmAction"><LoaderCircle v-if="busy.has('confirm')" class="spinning" />{{ busy.has('confirm') ? '处理中…' : confirm?.kind === 'run' ? '确认运行' : '确认删除' }}</button></template></AutomationModal>
